/**
 * Curated business context metadata for scope items.
 *
 * Maps SAP scope item IDs to business-friendly descriptions,
 * affected SAP modules, key configuration areas, master data
 * requirements, and cross-scope dependencies.
 *
 * This data was manually curated from SAP Best Practices 2508
 * documentation analysis. It is NOT auto-generated.
 *
 * Used by:
 * - BusinessQuestionCard (activity-level business questions)
 * - ImplicationsPanel (classification impact display)
 * - Enhanced sidebar (process chain context)
 */

// --- Types ---

export interface ScopeItemModuleInfo {
  code: string;
  name: string;
}

export interface ScopeItemMasterData {
  objectName: string;
  sapCode?: string | undefined;
  description: string;
}

export interface ScopeItemDependency {
  scopeItemId: string;
  name: string;
  reason: string;
  type: "required" | "recommended" | "optional";
}

export interface ActivityMetadata {
  activityTitlePattern: string;
  businessQuestion: string;
  thinkAbout: string;
  modules: string[];
  configAreas: string[];
  masterDataNeeded: string[];
  effortCategory: "low" | "medium" | "high";
}

export interface ClassificationImplication {
  fitDescription: string;
  configureDescription: string;
  gapDescription: string;
  naDescription: string;
  naImpact: string;
}

export interface ScopeItemMetadata {
  id: string;
  businessName: string;
  businessDescription: string;
  modules: ScopeItemModuleInfo[];
  masterData: ScopeItemMasterData[];
  dependencies: ScopeItemDependency[];
  activityMetadata: ActivityMetadata[];
  defaultImplications: ClassificationImplication;
}

