// --- Helper Functions ---

/** Get metadata for a scope item, or null if not curated. */
export function getScopeItemMetadata(scopeItemId: string): ScopeItemMetadata | null {
  return SCOPE_ITEM_METADATA[scopeItemId] ?? null;
}

/** Get activity metadata matching an activity title within a scope item. */
export function getActivityMetadata(
  scopeItemId: string,
  activityTitle: string,
): ActivityMetadata | null {
  const scopeMeta = SCOPE_ITEM_METADATA[scopeItemId];
  if (!scopeMeta) return null;

  // Try exact substring match first, then increasingly fuzzy
  for (const am of scopeMeta.activityMetadata) {
    if (activityTitle.includes(am.activityTitlePattern)) {
      return am;
    }
  }

  // Try case-insensitive match
  const lowerTitle = activityTitle.toLowerCase();
  for (const am of scopeMeta.activityMetadata) {
    if (lowerTitle.includes(am.activityTitlePattern.toLowerCase())) {
      return am;
    }
  }

  return null;
}

/** Get all modules for a scope item. */
export function getModulesForScopeItem(scopeItemId: string): ScopeItemModuleInfo[] {
  return SCOPE_ITEM_METADATA[scopeItemId]?.modules ?? [];
}

/** Get all dependencies for a scope item. */
export function getDependenciesForScopeItem(scopeItemId: string): ScopeItemDependency[] {
  return SCOPE_ITEM_METADATA[scopeItemId]?.dependencies ?? [];
}
